import{_ as a,a0 as p,w as l,s as m,I as n,x as t,a1 as o,A as r,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux 移动或重命名文件/目录－mv 的10个实用例子 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 移动或重命名文件/目录－mv 的10个实用例子 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 移动或重命名文件/目录－mv 的10个实用例子 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 移动或重命名文件/目录－mv 的10个实用例子 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples","title":"Linux 移动或重命名文件/目录－mv 的10个实用例子","tag":"201403","desc":""},"relativePath":"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples.md","filePath":"[post].md"}'),d={name:"201403/Moving or Rename File ／ Directory in Linux - 10 Practical mv Command Examples.md"};function g(f,e,c,x,h,u){const i=p("Link");return l(),m("div",null,[e[16]||(e[16]=n("h1",{id:"linux-移动或重命名文件-目录-mv-的10个实用例子",tabindex:"-1"},[t("Linux 移动或重命名文件/目录－mv 的10个实用例子 "),n("a",{class:"header-anchor",href:"#linux-移动或重命名文件-目录-mv-的10个实用例子","aria-label":"Permalink to “Linux 移动或重命名文件/目录－mv 的10个实用例子”"},"​")],-1)),n("p",null,[e[1]||(e[1]=t("熟悉了 ",-1)),o(i,{href:"http://linux.cn/article-2687-1.html"},{default:r(()=>[...e[0]||(e[0]=[t("复制命令",-1)])]),_:1}),e[2]||(e[2]=t("，下一个相关的命令就是 mv 命令。当你想要将文件从一个位置移动到另一个地方并且不想复制它，那么",-1)),e[3]||(e[3]=n("strong",null,"mv 命令",-1)),e[4]||(e[4]=t("是完成这个任务的首选。",-1))]),e[17]||(e[17]=s(`<h3 id="初识-mv-命令" tabindex="-1">初识 mv 命令 <a class="header-anchor" href="#初识-mv-命令" aria-label="Permalink to “初识 mv 命令”">​</a></h3><p>mv 命令是一个与<strong>cp</strong>类似的命令，但是它<strong>并非</strong>创建文件或目录的复制品/副本。不管你在使用什么版本的Linux系统，mv 都默认安装在你的Linux系统上了。来看一下 mv 命令在日常操作中的一些例子。</p><h4 id="_1-移动文件" tabindex="-1">1.移动文件 <a class="header-anchor" href="#_1-移动文件" aria-label="Permalink to “1.移动文件”">​</a></h4><p>移动文件时需要注意的是文件的源地址和目标地址<strong>必须不同</strong>。这里有个例子，想要将<strong>file_1.txt</strong>文件从当前目录移动到其它目录，以<strong>/home/pungki/</strong>为例，语法应该如下：</p><pre><code>$ mv file_1.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv.png" alt="mv command"></p><p>如我们所见，当我们移动 file_txt 文件时，先前目录的 file_1.txt 就<strong>被删除了</strong>。</p><h4 id="_2-移动多个文件" tabindex="-1">2.移动多个文件 <a class="header-anchor" href="#_2-移动多个文件" aria-label="Permalink to “2.移动多个文件”">​</a></h4><p>如果想一次移动多个文件，我们可以将他们放在一行并用空格分开。</p><pre><code>$ mv file_2.txt file_3.txt file_4.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_multiple.png" alt="Move multiple files"></p><p>如果你的文件有规律可循的话那么你就可以使用通配符。比如，为了移除所有以<strong>.txt</strong>为扩展名的文件，我们可以用下面的命令：</p><pre><code>$ mv *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_pattern.png" alt="Move using pattern"></p><h4 id="_3-移动目录" tabindex="-1">3.移动目录 <a class="header-anchor" href="#_3-移动目录" aria-label="Permalink to “3.移动目录”">​</a></h4><p>不同于复制命令，用 mv 命令移动目录相当直接。移动目录你可以使用不带选项的 mv 命令。看下面的截图就一目了然了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_directory.png" alt="Moving directory"></p><h4 id="_4-重命名文件或目录" tabindex="-1">4.重命名文件或目录 <a class="header-anchor" href="#_4-重命名文件或目录" aria-label="Permalink to “4.重命名文件或目录”">​</a></h4><p>我们也用 mv 命令来重命名文件或目录。不过目标位置和源位置必须相同才可以。然后文件名必须不同。</p><p>假定我们当前所在目录为<strong>/home/pungki/Documents</strong>，而我们想将<strong>file_1.txt重命名为file_2.txt</strong>。那么命令应该如下：</p><pre><code>$ mv file_1.txt file_2.txt
</code></pre><p>如果是绝对路径，它应该像下面这样：</p><pre><code>$ mv /home/pungki/Documents/file_1.txt /home/pungki/Documents/file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ren_file.png" alt="Renaming file"></p><h4 id="_5-重命名目录" tabindex="-1">5. 重命名目录 <a class="header-anchor" href="#_5-重命名目录" aria-label="Permalink to “5. 重命名目录”">​</a></h4><p>上一段的规则同样适用于目录。请看这个例子：</p><pre><code>$ mv directory_1/ directory_2/
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/ren_directory.png" alt="Renaming directory"></p><h4 id="_6-打印移动信息" tabindex="-1">6. 打印移动信息 <a class="header-anchor" href="#_6-打印移动信息" aria-label="Permalink to “6. 打印移动信息”">​</a></h4><p>当你移动或重命名一大堆文件或目录时，你可能会想在不去目标位置去查看的情况下知道你自己的命令是否成功地执行了。这就要用到<strong>-v</strong>选项了。</p><pre><code>$ mv -v *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_v.png" alt="mv with verbose mode"></p><p>该方法同样适用于目录。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_v_directory.png" alt="mv directory with verbose mode"></p><h4 id="_7-使用交互模式" tabindex="-1">7. 使用交互模式 <a class="header-anchor" href="#_7-使用交互模式" aria-label="Permalink to “7. 使用交互模式”">​</a></h4><p>当你将文件移动到其它位置，而那个位置恰好有同样的文件，这时 mv 命令会覆盖掉原来的文件。对于mv的这一行为一般不会有什么提示。如果想产生一个关于覆盖文件的提示，我们可以使用<strong>-i</strong>选项。（译注：通常发行版会通过alias命令，将-i作为默认选项，所以会有提示。）</p><p>假设我们想将 file_1.txt 移动到 /home/pungki/office。同时，/home/pungki/office 目录下已经有file_1.txt文件了。</p><pre><code>$ mv -i file_1.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_interactive.png" alt="mv with interactive mode"></p><p>这个提示会让我们知道目标位置处file_1.txt的存在。如果我们按<strong>y</strong>键，那么那个文件将会被删除，否则不会。</p><h4 id="_8-使用更新选项" tabindex="-1">8. 使用更新选项 <a class="header-anchor" href="#_8-使用更新选项" aria-label="Permalink to “8. 使用更新选项”">​</a></h4><p>－i 选项会提示我们关于覆盖文件的提示，而 －u 则只在源文件比目标文件新时才执行更新。让我们看一看下面的例子：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_u.png" alt="Update only newer"></p><p>假如 file_1.txt 和 file_2.txt有如下特点：</p><pre><code>File_1.txt has 84 bytes file size and it last modified time is 12:00
File_2.txt has 0 bytes file size and it last modified time is 11:59
</code></pre><p>我们想将它们移动到 /home/pungki/office 目录下。*<strong>但是目标地址</strong>已经有file_1.txt和file_2.txt了。</p><p>我们用下面的命令将file_1.txt 和file_2.txt从当前目录移动到/home/pungki/office</p><pre><code>$ mv -uv *.txt /home/pungki/office
</code></pre><p>可以看到这些文件被移动了。能移动这些文件是因为它们最近的修改时间戳比 /home/pungki/office 目录中的文件新。</p><h4 id="_9-不要覆盖任何已存在的文件" tabindex="-1">9.不要覆盖任何已存在的文件 <a class="header-anchor" href="#_9-不要覆盖任何已存在的文件" aria-label="Permalink to “9.不要覆盖任何已存在的文件”">​</a></h4><p>如果<strong>-i</strong>选项询问我们是否要覆盖文件，那么 -n 选项将不会允许我们覆盖任何已存在的文件。</p><p>继续使用第8点中的例子，如果我们将<strong>-u 换成 -n</strong>同时加上<strong>-v</strong>选项，那么我们会看到没有任何文件移动到了 /home/pungki/office 目录下。</p><pre><code>$ mv -vn *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_n.png" alt="No overwrite"></p><h4 id="_10-复制时创建备份" tabindex="-1">10. 复制时创建备份 <a class="header-anchor" href="#_10-复制时创建备份" aria-label="Permalink to “10. 复制时创建备份”">​</a></h4><p>默认情况下，移动文件将会覆盖已存在的目标文件。但是如果我们移动错了文件而目标文件已经被新的文件覆盖了，这时应该怎么办才好呢？<strong>有没有一种方法可以恢复之前的文件呢？答案是肯定的</strong>。我们可以用<strong>-b</strong>选项。该选项会在新文件覆盖旧文件时将旧文件做备份。这里我们还以第8点为例。</p><pre><code>$ mv -bv *.txt /home/pungki/office
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/mv_b.png" alt="Backup option"></p><p>如截图中所见，在 /home/pungki/office 目录下出现了名为<strong>file_1.txt~ and file_2.txt~ 的文件。那个波浪符号（～）意味着</strong>这些文件是备份文件。从它们的属性中我们可以看到，这些文件比file_1.txt和file_2.txt要旧。</p><h4 id="_11-无条件覆盖已经存在的文件" tabindex="-1">11. 无条件覆盖已经存在的文件 <a class="header-anchor" href="#_11-无条件覆盖已经存在的文件" aria-label="Permalink to “11. 无条件覆盖已经存在的文件”">​</a></h4><p>（译注：这一节是译者补充的，原文遗漏了这个重要选项）</p><p>当你希望无论如何都覆盖已经存在的文件或目录时，你可以使用 -f 选项。如果同时指定了 -f 选项和 -i 或 -n 选项，则 -f 选项会覆盖它们——即不进行任何提示而覆盖，所以，在使用此参数时，知道你在做什么。</p><pre><code>$ mv -f *.txt /home/pungki/office
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>移动文件和目录命令是Linux系统的基本命令。通常你可以通过<strong>man mv</strong> 或者 <strong>mv --help</strong>显示mv的手册页以了解更多详细信息。</p><hr>`,66)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),o(i,{href:"http://linoxide.com/linux-command/mv-command-linux/"},{default:r(()=>[...e[5]||(e[5]=[t("http://linoxide.com/linux-command/mv-command-linux/",-1)])]),_:1})]),n("p",null,[e[9]||(e[9]=t("译者：",-1)),o(i,{href:"https://github.com/Linchenguang"},{default:r(()=>[...e[7]||(e[7]=[t("Linchenguang",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:r(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),o(i,{href:"http://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const b=a(d,[["render",g]]);export{k as __pageData,b as default};
